'use client';

import { Playfair_Display, Roboto } from 'next/font/google';

const playfair = Playfair_Display({
  subsets: ['latin'],
  weight: ['400', '700'],
  variable: '--font-playfair',
  display: 'swap',
});

const roboto = Roboto({
  subsets: ['latin'],
  weight: ['300', '400', '500'],
  variable: '--font-roboto',
  display: 'swap',
});

export default function BlogHeader() {
  return (
    <header className={`${playfair.variable} ${roboto.variable}`}>
      <h1 style={{ fontFamily: 'var(--font-playfair)', fontWeight: 700, fontSize: '2.5rem' }}>
        My Personal Blog
      </h1>
      <p style={{ fontFamily: 'var(--font-roboto)', fontWeight: 300, fontSize: '1.1rem', opacity: 0.8 }}>
        Thoughts, ideas, and musings
      </p>
    </header>
  );
}

